import numpy as np

def covers_circle(c_seq, signs):
    x = 0
    covered_intervals = []
    for i in range(len(c_seq)):
        c = c_seq[i]
        s = signs[i]
        if s == 1:
            start, end = x, x + c
        else:
            start, end = x - c, x

        # Normalize to [0, 1]
        start_norm = start % 1
        end_norm = end % 1

        if s == 1:
            if start_norm < end_norm:
                if end_norm - start_norm == c:
                    covered_intervals.append((start_norm, end_norm))
                else:
                    # Wraps around
                    covered_intervals.append((start_norm, 1.0))
                    covered_intervals.append((0.0, end_norm))
            else:
                # This case should not happen if end_norm - start_norm is not c
                # but let's be careful
                covered_intervals.append((start_norm, 1.0))
                covered_intervals.append((0.0, end_norm))
        else:
            # s == -1, arc is [x-c, x]
            # start is x-c, end is x
            # let's use the same logic as s=1 but with start=x-c and end=x
            # Wait, the distance is always c.
            # The arc is from x-c to x.
            # In terms of [0, 1), it's the interval of length c ending at x.
            # Let's just use the same logic:
            start_norm = (x - c) % 1
            end_norm = x % 1
            if start_norm < end_norm:
                if end_norm - start_norm == c:
                    covered_intervals.append((start_norm, end_norm))
                else:
                    covered_intervals.append((start_norm, 1.0))
                    covered_intervals.append((0.0, end_norm))
            else:
                covered_intervals.append((start_norm, 1.0))
                covered_intervals.append((0.0, end_norm))

        x = (x + s * c) % 1

    # Check if union of intervals covers [0, 1]
    covered_intervals.sort()
    if not covered_intervals:
        return False

    merged_start, merged_end = covered_intervals[0]
    for next_start, next_end in covered_intervals[1:]:
        if next_start <= merged_end:
            merged_end = max(merged_end, next_end)
        else:
            return False

    return merged_end >= 1.0 - 1e-9 and merged_start <= 1e-9

