def is_forced_to_cover(c_seq):
    # Use a more efficient way to check all signs
    # We can use recursion with pruning
    def check_all(idx, x, covered_intervals):
        if idx == len(c_seq):
            # Final check
            intervals = sorted(covered_intervals)
            if not intervals: return False
            m_s, m_e = intervals[0]
            for n_s, n_e in intervals[1:]:
                if n_s <= m_e + 1e-9:
                    m_e = max(m_e, n_e)
                else:
                    return False
            return m_e >= 1.0 - 1e-9 and m_s <= 1e-9

        # Try s = 1
        c = c_seq[idx]
        s_norm = x % 1
        e_norm = (x + c) % 1
        new_intervals = covered_intervals[:]
        if s_norm < e_norm and abs(e_norm - s_norm - c) < 1e-9:
            new_intervals.append((s_norm, e_norm))
        else:
            new_intervals.append((s_norm, 1.0))
            new_intervals.append((0.0, e_norm))
        if not check_all(idx + 1, (x + c) % 1, new_intervals):
            return False

        # Try s = -1
        s_norm = (x - c) % 1
        e_norm = x % 1
        new_intervals = covered_intervals[:]
        if s_norm < e_norm and abs(e_norm - s_norm - c) < 1e-9:
            new_intervals.append((s_norm, e_norm))
        else:
            new_intervals.append((s_norm, 1.0))
            new_intervals.append((0.0, e_norm))
        if not check_all(idx + 1, (x - c) % 1, new_intervals):
            return False

        return True

    return check_all(0, 0, [])

